// src/slug.ts
function toPortalSlug(name) {
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").replace(/^[^a-z]+/, "").slice(0, 100).replace(/-+$/, "");
  return slug || "my-portal";
}

// src/write-tracker.ts
function trackWrites(api) {
  let wrote = false;
  return {
    api: {
      async request(method, path, body) {
        const result = await api.request(method, path, body);
        if (method !== "GET") wrote = true;
        return result;
      }
    },
    wrote: () => wrote
  };
}

